// ═══ AtomicInteger BASIC OPERATIONS ═══
AtomicInteger counter = new AtomicInteger(0);

counter.get();                      // read current value (volatile read)
counter.set(100);                   // set value (volatile write)
counter.incrementAndGet();          // ++counter (atomic, returns new value)
counter.getAndIncrement();          // counter++ (atomic, returns old value)
counter.decrementAndGet();          // --counter
counter.addAndGet(50);              // counter += 50 (atomic)
counter.compareAndSet(100, 200);    // if current==100, set to 200 (CAS)
counter.getAndUpdate(v -> v * 2);   // atomic: read old, apply fn, write new
counter.updateAndGet(v -> v + 10);  // atomic: apply fn, return new value
counter.accumulateAndGet(5, Integer::sum); // atomic: accumulate with function

// ═══ CAS INTERNALS — how incrementAndGet works ═══
// Source (simplified from OpenJDK):
public int incrementAndGet() {
    int prev, next;
    do {
        prev = get();           // Step 1: volatile read current value
        next = prev + 1;        // Step 2: compute new value
    } while (!compareAndSet(prev, next));  // Step 3: CAS — atomic!
    return next;
    // If another thread changed the value between step 1 and 3:
    //   compareAndSet fails (prev != current) → loop retries with fresh value!
    //   This is called a "CAS spin loop" — lock-free!
}

// compareAndSet is a SINGLE CPU instruction:
// x86: LOCK CMPXCHG [memory], expected, new
// ARM: LDREX + STREX (load-exclusive, store-exclusive)
// Atomicity guaranteed by hardware!

// ═══ WHEN TO USE AtomicInteger ═══
// (Recommended) Counters: transaction count, request count, error count
// (Recommended) Sequence generators: trade ID = atomic.incrementAndGet()
// (Recommended) Statistics: min/max/sum via updateAndGet
// (Recommended) Flags: AtomicBoolean for one-time initialization
// (Recommended) Reference swap: AtomicReference for immutable object swap

// ═══ WHEN NOT TO USE ═══
// (Avoid) Multi-variable invariants (low ≤ high) — need synchronized
// (Avoid) Check-then-act on different data — need synchronized
// (Avoid) Very high contention (100+ threads) — use LongAdder instead
//    (CAS retry loop degrades under extreme contention)
