package com.bank.atomic;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class AtomicIntegerTest {

    // ═══ Trade sequence generator — unique IDs ═══
    @Test
    void sequenceGenerator_uniqueIds() throws InterruptedException {
        AtomicInteger sequence = new AtomicInteger(0);
        int threads = 100;
        int idsPerThread = 1000;
        Set<Integer> allIds = ConcurrentHashMap.newKeySet();
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < idsPerThread; i++) {
                    int id = sequence.incrementAndGet();
                    allIds.add(id);
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(allIds).hasSize(threads * idsPerThread);  // ALL unique!
        assertThat(sequence.get()).isEqualTo(100_000);
    }

    // ═══ Active order count — increment/decrement ═══
    @Test
    void activeOrderCount_tracksConcurrently() throws InterruptedException {
        AtomicInteger activeOrders = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                activeOrders.incrementAndGet();    // new order
                try { Thread.sleep(10); } catch (InterruptedException e) { }
                activeOrders.decrementAndGet();    // order filled
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(activeOrders.get()).isEqualTo(0);  // all orders filled!
    }

    // ═══ CAS: compareAndSet ═══
    @Test
    void compareAndSet_conditionalUpdate() {
        AtomicInteger status = new AtomicInteger(0);  // 0=PENDING, 1=ACTIVE, 2=SETTLED

        // Only transition from PENDING(0) to ACTIVE(1)
        boolean activated = status.compareAndSet(0, 1);
        assertThat(activated).isTrue();
        assertThat(status.get()).isEqualTo(1);

        // Try again: already ACTIVE, not PENDING → fails!
        boolean activatedAgain = status.compareAndSet(0, 1);
        assertThat(activatedAgain).isFalse();
        assertThat(status.get()).isEqualTo(1);  // unchanged!
    }

    // ═══ updateAndGet: atomic function application ═══
    @Test
    void updateAndGet_atomicMax() throws InterruptedException {
        AtomicInteger maxPrice = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            final int price = ThreadLocalRandom.current().nextInt(1000, 5000);
            new Thread(() -> {
                maxPrice.updateAndGet(current -> Math.max(current, price));
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(maxPrice.get()).isGreaterThanOrEqualTo(1000);
        assertThat(maxPrice.get()).isLessThanOrEqualTo(5000);
    }

    // ═══ Volume accumulator ═══
    @Test
    void volumeAccumulator() throws InterruptedException {
        AtomicLong totalVolume = new AtomicLong(0);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                totalVolume.addAndGet(1000);  // each trade: 1000 shares
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(totalVolume.get()).isEqualTo(100_000);  // exact total!
    }
}
